        return -1;
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int n = (int) in.nval;
        in.nextToken();
        int m = (int) in.nval;
        int[][] edges = new int[m][3];
        for (int i = 0; i < m; i++)
            for (int j = 0; j < 3; j++) {
                in.nextToken();
                edges[i][j] = (int) in.nval;
            }
        in.nextToken();
        int s = (int) in.nval;
        in.nextToken();
        int t = (int) in.nval;
        in.nextToken();
        int b = (int) in.nval;
        int[] banned = new int[b];
        for (int i = 0; i < b; i++) {
            in.nextToken();
            banned[i] = (int) in.nval;
        }
        in.nextToken();
        int k = (int) in.nval;
        int[] required = new int[k];
        for (int i = 0; i < k; i++) {
            in.nextToken();
            required[i] = (int) in.nval;
        }
        System.out.println(shortestRoute(n, edges, s, t, banned, required));
    }
